  listChatMessages: {
    parameters: {
      query?: {
        limit?: number;
        /** @description Opaque next_cursor from the previous page; returns older messages */
        cursor?: string;
        /** @description suas-specs D-061 (owner-approved by ID 2026-11-09 3:19 PM PT), proposal text, not released: R8.11. A chat_thread_id of this request. Without it the live thread is returned. An earlier (released) thread is readable only by the requester; for anyone else, for a thread of another request, or for an unknown id, the response is the same 404. */
        thread?: string;
      };
      header?: never;
      path: {
        id: components['parameters']['IdPath'];
      };
      cookie?: never;
    };
    requestBody?: never;
    responses: {
      /** @description A page of messages */
      200: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          'application/json': components['schemas']['ChatMessagePage'];
        };
      };
      400: components['responses']['Error'];
      401: components['responses']['Error'];
      404: components['responses']['Error'];
      /** @description CHAT_UNAVAILABLE: the request has not been accepted yet */
      409: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          'application/json': components['schemas']['ErrorBody'];
        };
      };
    };
  };
  sendChatMessage: {
    parameters: {
      query?: {
        /** @description suas-specs D-061 (owner-approved by ID 2026-11-09 3:19 PM PT), proposal text, not released: R8.11. Optional. If given, it must be the live thread's chat_thread_id. An earlier (released) thread is read-only: naming it, a thread of another request, or an unknown id gets the same 404, and nothing is stored. */
        thread?: string;
      };
      header: {
        /** @description Client-chosen key that makes a retried command safe (API.md §7). Reusing it with a different request is 409 IDEMPOTENCY_CONFLICT. */
        'Idempotency-Key': components['parameters']['IdempotencyKey'];
      };
      path: {
        id: components['parameters']['IdPath'];
      };
      cookie?: never;
    };
    requestBody: {
      content: {
        'application/json': {
          body: string;
        };
      };
    };
    responses: {
      /** @description Replay of an earlier send with the same Idempotency-Key */
      200: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          'application/json': components['schemas']['ChatMessageSent'];
        };
      };
      /** @description Message stored; the other participant's live connections are notified on a best-effort basis */
      201: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          'application/json': components['schemas']['ChatMessageSent'];
        };
      };
      400: components['responses']['Error'];
      401: components['responses']['Error'];
      404: components['responses']['Error'];
      /** @description CHAT_UNAVAILABLE (not accepted yet), CHAT_CLOSED (a release ended the thread; it is read-only and the requester can still read it), or IDEMPOTENCY_CONFLICT */
      409: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          'application/json': components['schemas']['ErrorBody'];
        };
      };
    };
  };
